# Build a core PDFDoc/XRef harness (no cpp GlobalParams) to diagnose Parser::makeStream with MSan.
res = await self.shell.run(r'''
cat > /tmp/core_harness.cpp <<'EOF'
#include <cstdio>
#include <cstdlib>
#include <vector>
#include "Object.h"
#include "Stream.h"
#include "PDFDoc.h"
#include "XRef.h"
int main(int argc, char **argv) {
  if (argc < 2) return 2;
  FILE *f = fopen(argv[1], "rb");
  if (!f) return 3;
  fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
  std::vector<char> buf(n>0?n:0);
  if (n>0) fread(buf.data(),1,n,f);
  fclose(f);
  MemStream *ms = new MemStream(buf.data(), 0, n, Object(objNull));
  PDFDoc doc(ms, nullptr, nullptr, nullptr);
  if (!doc.isOk()) return 0;
  XRef *xr = doc.getXRef();
  if (!xr) return 0;
  int num = xr->getNumObjects();
  for (int i=0; i<num && i<1000; i++) {
    Object o = xr->fetch(i, 0);
    if (o.isStream()) {
      Stream *s = o.getStream();
      s->reset();
      for (int k=0; k<1024; k++) { int c=s->getChar(); if (c==EOF) break; }
      s->close();
    }
  }
  return 0;
}
EOF
set -x
/usr/local/bin/clang++ -std=c++14 -O1 -fno-omit-frame-pointer -gline-tables-only -DFUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION \
