  /tmp/core_harness.cpp -o /tmp/core_harness \
  /work/poppler/libpoppler.a /work/lib/libfreetype.a -pthread 2>&1 | tee /tmp/core_harness_compile.log
ls -l /tmp/core_harness || true
''', timeout=120)
print(res.stdout[-8000:])
