# Build a minimal XRef-only harness to exercise Parser::makeStream without cpp GlobalParams/Catalog.
res = await self.shell.run(r'''
cat > /tmp/xref_harness.cpp <<'EOF'
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include "Object.h"
#include "Stream.h"
#include "XRef.h"

static long find_startxref(const char *data, long n) {
  const char *needle = "startxref";
  for (long i = n - 9; i >= 0; --i) {
    if (memcmp(data+i, needle, 9) == 0) {
      i += 9;
      while (i < n && (data[i]==' '||data[i]=='\t'||data[i]=='\r'||data[i]=='\n')) ++i;
      return strtol(data+i, nullptr, 10);
    }
  }
  return 0;
}
int main(int argc, char **argv) {
  if (argc < 2) return 2;
  FILE *f = fopen(argv[1], "rb");
  if (!f) return 3;
  fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
  std::vector<char> buf(n>0?n:0);
  if (n>0) fread(buf.data(),1,n,f);
  fclose(f);
  long sx = (argc >= 3) ? strtol(argv[2], nullptr, 0) : find_startxref(buf.data(), n);
  MemStream *ms = new MemStream(buf.data(), 0, n, Object(objNull));
