     2	# Local PoC submission script for Harbor CyberGym tasks.
     3	#
     4	# Mirrors the original CyberGym benchmark's submit.sh behavior:
     5	# the agent calls "bash submit.sh /path/to/poc", the script sends
     6	# the PoC to the task server, and prints the JSON response (exit code
     7	# + sanitizer output) so the agent can iterate and refine.
     8	
     9	# Display help message if no arguments provided or help flag used
    10	if [ "$1" == "-h" ] || [ "$1" == "--help" ] || [ -z "$1" ]; then
    11	    echo "Usage: $0 <poc_file_path>"
    12	    echo ""
    13	    echo "Submit a vulnerability proof-of-concept file for testing"
    14	    echo ""
    15	    echo "Arguments:"
    16	    echo "  <poc_file_path>    Path to the proof-of-concept file to submit"
    17	    echo ""
    18	    echo "Examples:"
    19	    echo "  $0 /path/to/poc"
    20	    exit 0
    21	fi
    22	
    23	POC_FILE="$1"
    24	
    25	# Check if file exists
    26	if [ ! -f "$POC_FILE" ]; then
    27	    echo "Error: File '$POC_FILE' not found!"
    28	    exit 1
    29	fi
    30	
    31	# Submit PoC to task server
    32	RESPONSE=$(curl -sf -X POST -F "poc=@${POC_FILE}" http://task-server:9111/submit 2>&1)
    33	CURL_RC=$?
    34	
    35	if [ $CURL_RC -ne 0 ]; then
    36	    echo "Error: failed to connect to task server (curl exit code: $CURL_RC)"
    37	    echo "$RESPONSE"
    38	    exit 1
    39	fi
    40	
    41	# Parse exit code from JSON response {"exit_code": N, "output": "..."}
    42	EXIT_CODE=$(echo "$RESPONSE" | grep -o '"exit_code": *[-0-9]*' | grep -o '[-0-9]*$')
    43	
    44	if [ -z "$EXIT_CODE" ]; then
    45	    echo "Error: unexpected response from task server: $RESPONSE"
    46	    exit 1
    47	fi
    48	
    49	# Save every submission so the verifier can try all of them (matches
    50	# original CyberGym behavior where poc.db keeps every attempt).
    51	mkdir -p /workspace/submissions
    52	SUBMIT_NUM=$(ls /workspace/submissions/ 2>/dev/null | wc -l)
    53	SUBMIT_NUM=$((SUBMIT_NUM + 1))
    54	cp "$POC_FILE" "/workspace/submissions/poc_$(printf '%03d' $SUBMIT_NUM)"
    55	
    56	# Also copy to /workspace/poc (latest submission)
    57	cp "$POC_FILE" /workspace/poc 2>/dev/null || true
    58	
    59	# Log submission response for post-run analysis.
    60	# Written to /logs/artifacts/ so Harbor collects it automatically.
    61	mkdir -p /logs/artifacts
    62	echo "=== poc_$(printf '%03d' $SUBMIT_NUM) ===" >> /logs/artifacts/submit_log.txt
    63	echo "$RESPONSE" >> /logs/artifacts/submit_log.txt
    64	echo "" >> /logs/artifacts/submit_log.txt
    65	
    66	# Print full JSON response (exit code + sanitizer output) so the agent
    67	# can see crash details and iterate intelligently — matches original
    68	# CyberGym server behavior.
    69	echo ""
    70	echo "$RESPONSE"
    71	
    72	# Exit 0 — the agent reads the result from the JSON output above,
    73	# matching original CyberGym behavior (submit.sh exits with curl's
    74	# exit code, which is 0 on success).
    75	exit 0
