  1358	void XRef::writeXRef(XRef::XRefWriter *writer, bool writeAllEntries) {
  1359	  //create free entries linked-list
  1360	  if (getEntry(0)->gen != 65535) {
  1361	    error(errInternal, -1, "XRef::writeXRef, entry 0 of the XRef is invalid (gen != 65535)\n");
  1362	  }
  1363	  int lastFreeEntry = 0;
  1364	  for (int i=0; i<size; i++) {
  1365	    if (getEntry(i)->type == xrefEntryFree) {
  1366	      getEntry(lastFreeEntry)->offset = i;
  1367	      lastFreeEntry = i;
  1368	    }
  1369	  }
  1370	  getEntry(lastFreeEntry)->offset = 0;
  1371	
  1372	  if (writeAllEntries) {
  1373	    writer->startSection(0, size);
  1374	    for (int i=0; i<size; i++) {
  1375	      XRefEntry *e = getEntry(i);
  1376	      if(e->gen > 65535) e->gen = 65535; //cap generation number to 65535 (required by PDFReference)
  1377	      writer->writeEntry(e->offset, e->gen, e->type);
  1378	    }
  1379	  } else {
  1380	    int i = 0;
  1381	    while (i < size) {
  1382	      int j;
  1383	      for(j=i; j<size; j++) { //look for consecutive entries
  1384	        if ((getEntry(j)->type == xrefEntryFree) && (getEntry(j)->gen == 0))
  1385	          break;
  1386	      }
  1387	      if (j-i != 0)
  1388	      {
  1389	        writer->startSection(i, j-i);
  1390	        for (int k=i; k<j; k++) {
  1391	          XRefEntry *e = getEntry(k);
  1392	          if(e->gen > 65535) e->gen = 65535; //cap generation number to 65535 (required by PDFReference)
  1393	          writer->writeEntry(e->offset, e->gen, e->type);
  1394	        }
  1395	        i = j;
  1396	      }
  1397	      else ++i;
  1398	    }
  1399	  }
