  1431	void XRef::XRefStreamWriter::writeEntry(Goffset offset, int gen, XRefEntryType type) {
  1432	  const int entryTotalSize = 1 + offsetSize + 2; /* type + offset + gen */
  1433	  char data[16];
  1434	  data[0] = (type==xrefEntryFree) ? 0 : 1;
  1435	  for (int i = offsetSize; i > 0; i--) {
  1436	    data[i] = offset & 0xff;
  1437	    offset >>= 8;
  1438	  }
  1439	  data[offsetSize + 1] = (gen >> 8) & 0xff;
  1440	  data[offsetSize + 2] = gen & 0xff;
  1441	  stmBuf->append(data, entryTotalSize);
  1442	}
