   592	      if ((c = getChar()) == EOF) {
   593	        return Object(objEOF);
   594	      }
   595	      if (comment) {
   596	        if (c == '\r' || c == '\n') {
   597	          comment = false;
   598	        }
   599	      } else if (c == '%') {
   600	        comment = true;
   601	      } else if (specialChars[c] != 1) {
   602	        break;
   603	      }
   604	    }
   605	    p = tokBuf;
   606	    *p++ = c;
