   120	char *Stream::getLine(char *buf, int size) {
   121	  int i;
   122	  int c;
   123	
   124	  if (lookChar() == EOF || size < 0)
   125	    return nullptr;
   126	  for (i = 0; i < size - 1; ++i) {
   127	    c = getChar();
   128	    if (c == EOF || c == '\n')
   129	      break;
   130	    if (c == '\r') {
   131	      if ((c = lookChar()) == '\n')
   132		getChar();
   133	      break;
   134	    }
   135	    buf[i] = c;
   136	  }
   137	  buf[i] = '\0';
   138	  return buf;
   139	}
