   117	  inline int doGetChars(int nChars, Guchar *buffer)
   118	  {
   119	    if (hasGetChars()) {
   120	      return getChars(nChars, buffer);
   121	    } else {
   122	      for (int i = 0; i < nChars; ++i) {
   123	        const int c = getChar();
   124	        if (likely(c != EOF)) buffer[i] = c;
   125	        else return i;
   126	      }
   127	      return nChars;
   128	    }
   129	  }
