   132	  {
   133	    Guchar readBuf[4096];
   134	    int readChars;
   135	    reset();
   136	    while ((readChars = doGetChars(4096, readBuf)) != 0) {
   137	      s->append((const char *)readBuf, readChars);
   138	    }
   139	  }
