   141	  inline Guchar *toUnsignedChars(int *length, int initialSize = 4096, int sizeIncrement = 4096)
   142	  {
   143	    int readChars;
   144	    Guchar *buf = (Guchar *)gmalloc(initialSize);
   145	    int size = initialSize;
   146	    *length = 0;
   147	    int charsToRead = initialSize;
   148	    bool continueReading = true;
   149	    reset();
   150	    while (continueReading && (readChars = doGetChars(charsToRead, &buf[*length])) != 0) {
   151	      *length += readChars;
   152	      if (readChars == charsToRead) {
   153	        if (lookChar() != EOF) {
   154	          size += sizeIncrement;
   155	          charsToRead = sizeIncrement;
   156	          buf = (Guchar *)grealloc(buf, size);
   157	        } else {
   158	          continueReading = false;
   159	        }
   160	      } else {
   161	        continueReading = false;
   162	      }
   163	    }
