   474	private:
   475	
   476	  bool fillBuf();
   477	  
   478	  bool hasGetChars() override { return true; }
   479	  int getChars(int nChars, Guchar *buffer) override
   480	    {
   481	      int n, m;
   482	
   483	      n = 0;
   484	      while (n < nChars) {
   485	        if (bufPtr >= bufEnd) {
   486	          if (!fillBuf()) {
   487	            break;
   488	          }
   489	        }
   490	        m = (int)(bufEnd - bufPtr);
   491	        if (m > nChars - n) {
   492	          m = nChars - n;
   493	        }
   494	        memcpy(buffer + n, bufPtr, m);
   495	        bufPtr += m;
   496	        n += m;
   497	      }
   498	      return n;
   499	    }
