   769	bool FileStream::fillBuf() {
   770	  int n;
   771	
   772	  bufPos += bufEnd - buf;
   773	  bufPtr = bufEnd = buf;
   774	  if (limited && bufPos >= start + length) {
   775	    return false;
   776	  }
   777	  if (limited && bufPos + fileStreamBufSize > start + length) {
   778	    n = start + length - bufPos;
   779	  } else {
   780	    n = fileStreamBufSize;
   781	  }
   782	  n = file->read(buf, n, offset);
   783	  if (n == -1) {
   784	    return false;
   785	  }
   786	  offset += n;
   787	  bufEnd = buf + n;
   788	  if (bufPtr >= bufEnd) {
   789	    return false;
   790	  }
   791	  return true;
   792	}
   793	
   794	void FileStream::setPos(Goffset pos, int dir) {
   795	  Goffset size;
   796	
   797	  if (dir >= 0) {
   798	    offset = bufPos = pos;
   799	  } else {
   800	    size = file->size();
   801	    if (pos > size)
   802	      pos = size;
   803	    offset = size - pos;
   804	    bufPos = offset;
   805	  }
   806	  bufPtr = bufEnd = buf;
   807	}
   808	
   809	void FileStream::moveStart(Goffset delta) {
   810	  start += delta;
   811	  bufPtr = bufEnd = buf;
   812	  bufPos = start;
   813	}
