   694	bool PDFDoc::checkLinearization() {
   695	  if (linearization == nullptr)
   696	    return false;
   697	  if (linearizationState == 1)
   698	    return true;
   699	  if (linearizationState == 2)
   700	    return false;
   701	  if (!hints) {
   702	    hints = new Hints(str, linearization, getXRef(), secHdlr);
   703	  }
   704	  if (!hints->isOk()) {
   705	    linearizationState = 2;
   706	    return false;
   707	  }
   708	  for (int page = 1; page <= linearization->getNumPages(); page++) {
   709	    Ref pageRef;
   710	
   711	    pageRef.num = hints->getPageObjectNum(page);
   712	    if (!pageRef.num) {
   713	      linearizationState = 2;
   714	      return false;
   715	    }
   716	
   717	    // check for bogus ref - this can happen in corrupted PDF files
   718	    if (pageRef.num < 0 || pageRef.num >= xref->getNumObjects()) {
   719	      linearizationState = 2;
   720	      return false;
   721	    }
   722	
   723	    pageRef.gen = xref->getEntry(pageRef.num)->gen;
   724	    Object obj = xref->fetch(pageRef.num, pageRef.gen);
   725	    if (!obj.isDict("Page")) {
   726	      linearizationState = 2;
   727	      return false;
   728	    }
   729	  }
   730	  linearizationState = 1;
   731	  return true;
   732	}
