extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  if (size < 10 || size > (1<<20)) return 0;
  MemStream *ms = new MemStream(reinterpret_cast<const char*>(data), 0, (Goffset)size, Object(objNull));
  PDFDoc doc(ms, nullptr, nullptr, nullptr);
  if (!doc.isOk()) return 0;
  XRef *xr = doc.getXRef();
  if (xr) {
    int num = xr->getNumObjects();
    if (num > 10000) num = 10000;
    for (int i=0; i<num; i++) {
      Object o = xr->fetch(i, 0);
      if (o.isStream()) readStream(o.getStream());
      else if (o.isArray()) {
        int n=o.arrayGetLength(); if (n>100) n=100;
        for(int j=0;j<n;j++){ Object a=o.arrayGet(j); if(a.isStream()) readStream(a.getStream()); }
