# Build a PDFDoc fuzzer with a prefilter to avoid known Lexer long-token UMR; search for other MSan findings.
res=await self.shell.run(r'''
cat > /tmp/pdfdoc_fuzzer_pf.cpp <<'EOF'
#include <cstdint>
#include <cstddef>
#include "Object.h"
#include "Stream.h"
#include "PDFDoc.h"
#include "XRef.h"
static bool is_delim(unsigned char c) {
  return c==0 || c==9 || c==10 || c==12 || c==13 || c==32 || c=='(' || c==')' || c=='<' || c=='>' || c=='[' || c==']' || c=='{' || c=='}' || c=='/' || c=='%';
}
static bool ok_input(const uint8_t* data, size_t size) {
  size_t run=0;
  for (size_t i=0;i<size;i++) {
    unsigned char c=data[i];
    if (is_delim(c)) run=0; else { if (++run > 96) return false; }
    if (c=='/') {
      size_t j=i+1; while (j<size && !is_delim(data[j])) j++;
      if (j-i-1 > 96) return false;
    }
  }
  return true;
}
static void readStream(Stream *s) { if(!s) return; s->reset(); for(int k=0;k<32768;k++){int c=s->getChar(); if(c==EOF) break;} s->close(); }
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  if (size < 10 || size > 4096 || !ok_input(data,size)) return 0;
  MemStream *ms = new MemStream(reinterpret_cast<const char*>(data), 0, (Goffset)size, Object(objNull));
  PDFDoc doc(ms, nullptr, nullptr, nullptr);
  if (!doc.isOk()) return 0;
  int pages=doc.getNumPages();
  for (int p=1;p<=pages && p<=20;p++) { Page *pg=doc.getPage(p); (void)pg; }
  XRef *xr = doc.getXRef();
  if (xr) {
    int num=xr->getNumObjects(); if (num>2000) num=2000;
    for (int i=0;i<num;i++) {
      Object o=xr->fetch(i,0);
      if (o.isStream()) readStream(o.getStream());
      else if (o.isDict()) { Object c=o.dictLookup("Contents"); if(c.isStream()) readStream(c.getStream()); }
    }
  }
  return 0;
}
EOF
