static long find_startxref(const char *data, long n) {
  const char *needle = "startxref";
  for (long i = n - 9; i >= 0; --i) {
    if (memcmp(data+i, needle, 9) == 0) {
      i += 9;
      while (i < n && (data[i]==' '||data[i]=='\t'||data[i]=='\r'||data[i]=='\n')) ++i;
      return strtol(data+i, nullptr, 10);
    }
  }
  return 0;
}
