static bool is_delim(unsigned char c) {
  return c==0 || c==9 || c==10 || c==12 || c==13 || c==32 || c=='(' || c==')' || c=='<' || c=='>' || c=='[' || c==']' || c=='{' || c=='}' || c=='/' || c=='%';
}
static bool ok_input(const uint8_t* data, size_t size) {
  size_t run=0;
  for (size_t i=0;i<size;i++) {
    unsigned char c=data[i];
    if (is_delim(c)) run=0; else { if (++run > 96) return false; }
    if (c=='/') {
      size_t j=i+1; while (j<size && !is_delim(data[j])) j++;
      if (j-i-1 > 96) return false;
    }
  }
  return true;
}
