   359	// Check for a %%EOF at the end of this stream
   360	bool PDFDoc::checkFooter() {
   361	  // we look in the last 1024 chars because Adobe does the same
   362	  char *eof = new char[1025];
   363	  Goffset pos = str->getPos();
   364	  str->setPos(1024, -1);
   365	  int i, ch;
   366	  for (i = 0; i < 1024; i++)
   367	  {
   368	    ch = str->getChar();
   369	    if (ch == EOF)
   370	      break;
   371	    eof[i] = ch;
   372	  }
   373	  eof[i] = '\0';
   374	
   375	  bool found = false;
   376	  for (i = i - 5; i >= 0; i--) {
   377	    if (strncmp (&eof[i], "%%EOF", 5) == 0) {
   378	      found = true;
   379	      break;
   380	    }
   381	  }
   382	  if (!found)
   383	  {
   384	    error(errSyntaxError, -1, "Document has not the mandatory ending %%EOF");
   385	    errCode = errDamaged;
   386	    delete[] eof;
   387	    return false;
   388	  }
   389	  delete[] eof;
   390	  str->setPos(pos);
   391	  return true;
