  1971	long long PDFDoc::strToLongLong(const char *s) {
  1972	  long long x, d;
  1973	  const char *p;
  1974	
  1975	  x = 0;
  1976	  for (p = s; *p && isdigit(*p & 0xff); ++p) {
  1977	    d = *p - '0';
  1978	    if (x > (LLONG_MAX - d) / 10) {
  1979	      break;
  1980	    }
  1981	    x = 10 * x + d;
  1982	  }
  1983	  return x;
  1984	}
