  1986	// Read the 'startxref' position.
  1987	Goffset PDFDoc::getStartXRef(bool tryingToReconstruct)
  1988	{
  1989	  if (startXRefPos == -1) {
  1990	
  1991	    if (isLinearized(tryingToReconstruct)) {
  1992	      char buf[linearizationSearchSize+1];
  1993	      int c, n, i;
  1994	
  1995	      str->setPos(0);
  1996	      for (n = 0; n < linearizationSearchSize; ++n) {
  1997	        if ((c = str->getChar()) == EOF) {
  1998	          break;
  1999	        }
  2000	        buf[n] = c;
  2001	      }
  2002	      buf[n] = '\0';
  2003	
  2004	      // find end of first obj (linearization dictionary)
  2005	      startXRefPos = 0;
  2006	      for (i = 0; i < n; i++) {
  2007	        if (!strncmp("endobj", &buf[i], 6)) {
  2008		  i += 6;
  2009		  //skip whitespace 
  2010		  while (buf[i] && Lexer::isSpace(buf[i])) ++i;
  2011		  startXRefPos = i;
  2012		  break;
  2013	        }
  2014	      }
  2015	    } else {
  2016	      char buf[xrefSearchSize+1];
  2017	      const char *p;
  2018	      int c, n, i;
  2019	
  2020	      // read last xrefSearchSize bytes
  2021	      int segnum = 0;
  2022	      int maxXRefSearch = 24576;
  2023	      if (str->getLength() < maxXRefSearch) maxXRefSearch = str->getLength();
  2024	      for (; (xrefSearchSize - 16) * segnum < maxXRefSearch; segnum++) {
  2025	        str->setPos((xrefSearchSize - 16) * segnum + xrefSearchSize, -1);
  2026	        for (n = 0; n < xrefSearchSize; ++n) {
  2027	          if ((c = str->getChar()) == EOF) {
  2028	            break;
  2029	          }
  2030	          buf[n] = c;
  2031	        }
  2032	        buf[n] = '\0';
  2033	
  2034	        // find startxref
  2035	        for (i = n - 9; i >= 0; --i) {
  2036	          if (!strncmp(&buf[i], "startxref", 9)) {
  2037	            break;
  2038	          }
  2039	        }
  2040	        if (i < 0) {
  2041	          startXRefPos = 0;
  2042	        } else {
  2043	          for (p = &buf[i + 9]; isspace(*p); ++p);
  2044	          startXRefPos = strToLongLong(p);
  2045	          break;
  2046	        }
  2047	      }
  2048	    }
  2049	
  2050	  }
  2051	
  2052	  return startXRefPos;
  2053	}
