    68	Lexer::Lexer(XRef *xrefA, Stream *str) {
    69	  lookCharLastValueCached = LOOK_VALUE_NOT_CACHED;
    70	  xref = xrefA;
    71	
    72	  curStr = Object(str);
    73	  streams = new Array(xref);
    74	  streams->add(curStr.copy());
    75	  strPtr = 0;
    76	  freeArray = true;
    77	  curStr.streamReset();
    78	}
    79	
    80	Lexer::Lexer(XRef *xrefA, Object *obj) {
    81	  lookCharLastValueCached = LOOK_VALUE_NOT_CACHED;
    82	  xref = xrefA;
    83	
    84	  if (obj->isStream()) {
    85	    streams = new Array(xref);
    86	    freeArray = true;
    87	    streams->add(obj->copy());
    88	  } else {
    89	    streams = obj->getArray();
    90	    freeArray = false;
    91	  }
    92	  strPtr = 0;
    93	  if (streams->getLength() > 0) {
    94	    curStr = streams->get(strPtr);
    95	    if (curStr.isStream()) {
    96	      curStr.streamReset();
    97	    }
    98	  }
    99	}
