   110	int Lexer::getChar(bool comesFromLook) {
   111	  int c;
   112	
   113	  if (LOOK_VALUE_NOT_CACHED != lookCharLastValueCached) {
   114	    c = lookCharLastValueCached;
   115	    lookCharLastValueCached = LOOK_VALUE_NOT_CACHED;
   116	    return c;
   117	  }
   118	
   119	  c = EOF;
   120	  while (curStr.isStream() && (c = curStr.streamGetChar()) == EOF) {
   121	    if (comesFromLook == true) {
   122	      return EOF;
   123	    } else {
   124	      curStr.streamClose();
   125	      curStr = Object();
   126	      ++strPtr;
   127	      if (strPtr < streams->getLength()) {
   128		curStr = streams->get(strPtr);
   129		if (curStr.isStream()) {
   130		  curStr.streamReset();
   131		}
   132	      }
   133	    }
   134	  }
   135	  return c;
   136	}
   137	
   138	int Lexer::lookChar() {
   139	  
   140	  if (LOOK_VALUE_NOT_CACHED != lookCharLastValueCached) {
   141	    return lookCharLastValueCached;
   142	  }
   143	  lookCharLastValueCached = getChar(true);
   144	  if (lookCharLastValueCached == EOF) {
   145	    lookCharLastValueCached = LOOK_VALUE_NOT_CACHED;
   146	    return EOF;
   147	  } else {
   148	    return lookCharLastValueCached;
   149	  }
   150	}
