   386	
   387	int XRef::reserve(int newSize)
   388	{
   389	  if (newSize > capacity) {
   390	
   391	    int realNewSize;
   392	    for (realNewSize = capacity ? 2 * capacity : 1024;
   393	          newSize > realNewSize && realNewSize > 0;
   394	          realNewSize <<= 1) ;
   395	    if ((realNewSize < 0) ||
   396	        (realNewSize >= INT_MAX / (int)sizeof(XRefEntry))) {
   397	      return 0;
   398	    }
   399	
   400	    void *p = greallocn_checkoverflow(entries, realNewSize, sizeof(XRefEntry));
   401	    if (p == nullptr) {
   402	      return 0;
   403	    }
   404	
   405	    entries = (XRefEntry *) p;
   406	    capacity = realNewSize;
   407	
   408	  }
   409	
   410	  return capacity;
   411	}
   412	
   413	int XRef::resize(int newSize)
   414	{
   415	  if (newSize > size) {
   416	
   417	    if (reserve(newSize) < newSize) return size;
   418	
   419	    for (int i = size; i < newSize; ++i) {
   420	      entries[i].offset = -1;
   421	      entries[i].type = xrefEntryNone;
   422	      new (&entries[i].obj) Object(objNull);
   423	      entries[i].flags = 0;
   424	      entries[i].gen = 0;
   425	    }
   426	  } else {
   427	    for (int i = newSize; i < size; i++) {
   428	      entries[i].obj.~Object();
   429	    }
   430	  }
   431	
   432	  size = newSize;
   433	
   434	  return size;
   435	}
