   437	/* Read one xref table section.  Also reads the associated trailer
   438	 * dictionary, and returns the prev pointer (if any).
   439	 * Arguments:
   440	 *   pos                Points to a Goffset containing the offset of the XRef
   441	 *                      section to be read. If a prev pointer is found, *pos is
   442	 *                      updated with its value
   443	 *   followedXRefStm    Used in case of nested readXRef calls to spot circular
   444	 *                      references in XRefStm pointers
   445	 *   xrefStreamObjsNum  If not NULL, every time a XRef stream is encountered,
   446	 *                      its object number is appended
   447	 * Return value:
   448	 *   true if a prev pointer is found, otherwise false
   449	 */
   450	bool XRef::readXRef(Goffset *pos, std::vector<Goffset> *followedXRefStm, std::vector<int> *xrefStreamObjsNum) {
   451	  Parser *parser;
   452	  Object obj;
   453	  bool more;
   454	
   455	  if (unlikely(start > (LLONG_MAX - *pos))) {
   456	    ok = false;
   457	    return false;
   458	  }
   459	
   460	  // start up a parser, parse one token
   461	  parser = new Parser(nullptr,
   462		     new Lexer(nullptr,
   463		       str->makeSubStream(start + *pos, false, 0, Object(objNull))),
   464		     true);
   465	  obj = parser->getObj(true);
   466	
   467	  // parse an old-style xref table
   468	  if (obj.isCmd("xref")) {
   469	    more = readXRefTable(parser, pos, followedXRefStm, xrefStreamObjsNum);
   470	
   471	  // parse an xref stream
   472	  } else if (obj.isInt()) {
   473	    const int objNum = obj.getInt();
   474	    if (obj = parser->getObj(true), !obj.isInt()) {
   475	      goto err1;
   476	    }
   477	    if (obj = parser->getObj(true), !obj.isCmd("obj")) {
   478	      goto err1;
   479	    }
   480	    if (obj = parser->getObj(), !obj.isStream()) {
   481	      goto err1;
   482	    }
   483	    if (trailerDict.isNone()) {
   484	      xRefStream = true;
   485	    }
   486	    if (xrefStreamObjsNum) {
   487	      xrefStreamObjsNum->push_back(objNum);
   488	    }
   489	    more = readXRefStream(obj.getStream(), pos);
   490	
   491	  } else {
   492	    goto err1;
   493	  }
   494	
   495	  delete parser;
   496	  return more;
   497	
   498	 err1:
   499	  delete parser;
   500	  ok = false;
   501	  return false;
   502	}
   503	
   504	bool XRef::readXRefTable(Parser *parser, Goffset *pos, std::vector<Goffset> *followedXRefStm, std::vector<int> *xrefStreamObjsNum) {
   505	  XRefEntry entry;
   506	  bool more;
   507	  Object obj, obj2;
   508	  Goffset pos2;
   509	  int first, n;
   510	
   511	  while (1) {
   512	    obj = parser->getObj(true);
   513	    if (obj.isCmd("trailer")) {
   514	      break;
   515	    }
   516	    if (!obj.isInt()) {
   517	      goto err0;
   518	    }
   519	    first = obj.getInt();
   520	    obj = parser->getObj(true);
   521	    if (!obj.isInt()) {
   522	      goto err0;
   523	    }
   524	    n = obj.getInt();
   525	    if (first < 0 || n < 0 || first > INT_MAX - n) {
   526	      goto err0;
   527	    }
   528	    if (first + n > size) {
   529	      if (resize(first + n) != first + n) {
   530	        error(errSyntaxError, -1, "Invalid 'obj' parameters'");
   531	        goto err0;
   532	      }
   533	    }
   534	    for (int i = first; i < first + n; ++i) {
   535	      obj = parser->getObj(true);
   536	      if (obj.isInt()) {
   537		entry.offset = obj.getInt();
   538	      } else if (obj.isInt64()) {
   539		entry.offset = obj.getInt64();
   540	      } else {
   541		goto err0;
   542	      }
   543	      obj = parser->getObj(true);
   544	      if (!obj.isInt()) {
   545		goto err0;
   546	      }
   547	      entry.gen = obj.getInt();
   548	      entry.flags = 0;
   549	      obj = parser->getObj(true);
   550	      if (obj.isCmd("n")) {
   551		entry.type = xrefEntryUncompressed;
   552	      } else if (obj.isCmd("f")) {
   553		entry.type = xrefEntryFree;
   554	      } else {
   555		goto err0;
   556	      }
   557	      if (entries[i].offset == -1) {
   558		entries[i].offset = entry.offset;
   559		entries[i].gen = entry.gen;
   560		entries[i].type = entry.type;
   561		entries[i].flags = entry.flags;
   562		entries[i].obj.setToNull();
   563	
   564		// PDF files of patents from the IBM Intellectual Property
   565		// Network have a bug: the xref table claims to start at 1
   566		// instead of 0.
   567		if (i == 1 && first == 1 &&
   568		    entries[1].offset == 0 && entries[1].gen == 65535 &&
   569		    entries[1].type == xrefEntryFree) {
   570		  i = first = 0;
   571		  entries[0].offset = 0;
   572		  entries[0].gen = 65535;
   573		  entries[0].type = xrefEntryFree;
   574		  entries[0].flags = entries[1].flags;
   575		  entries[0].obj = std::move(entries[1].obj);
   576	
   577		  entries[1].offset = -1;
   578		  entries[1].obj.setToNull();
   579		}
   580	      }
   581	    }
   582	  }
   583	
   584	  // read the trailer dictionary
   585	  obj = parser->getObj();
   586	  if (!obj.isDict()) {
   587	    goto err0;
   588	  }
   589	
   590	  // get the 'Prev' pointer
   591	  obj2 = obj.getDict()->lookupNF("Prev");
   592	  if (obj2.isInt() || obj2.isInt64()) {
   593	    if (obj2.isInt())
   594	      pos2 = obj2.getInt();
   595	    else
   596	      pos2 = obj2.getInt64();
   597	    if (pos2 != *pos) {
   598	      *pos = pos2;
   599	      more = true;
   600	    } else {
   601	      error(errSyntaxWarning, -1, "Infinite loop in xref table");
   602	      more = false;
   603	    }
   604	  } else if (obj2.isRef()) {
   605	    // certain buggy PDF generators generate "/Prev NNN 0 R" instead
   606	    // of "/Prev NNN"
   607	    pos2 = (Guint)obj2.getRefNum();
   608	    if (pos2 != *pos) {
   609	      *pos = pos2;
   610	      more = true;
   611	    } else {
   612	      error(errSyntaxWarning, -1, "Infinite loop in xref table");
   613	      more = false;
   614	    }
   615	  } else {
   616	    more = false;
   617	  }
   618	
   619	  // save the first trailer dictionary
   620	  if (trailerDict.isNone()) {
   620	  if (trailerDict.isNone()) {
   621	    trailerDict = obj.copy();
   622	  }
   623	
   624	  // check for an 'XRefStm' key
   625	  obj2 = obj.getDict()->lookup("XRefStm");
   626	  if (obj2.isInt() || obj2.isInt64()) {
   627	    if (obj2.isInt())
   628	      pos2 = obj2.getInt();
   629	    else
   630	      pos2 = obj2.getInt64();
   631	    for (size_t i = 0; ok == true && i < followedXRefStm->size(); ++i) {
   632	      if (followedXRefStm->at(i) == pos2) {
   633	        ok = false;
   634	      }
   635	    }
   636	    if (ok) {
   637	      followedXRefStm->push_back(pos2);
   638	      readXRef(&pos2, followedXRefStm, xrefStreamObjsNum);
   639	    }
   640	    if (!ok) {
   641	      goto err0;
   642	    }
   643	  }
   644	
   645	  return more;
   646	
   647	 err0:
   648	  ok = false;
   649	  return false;
   650	}
   651	
   652	bool XRef::readXRefStream(Stream *xrefStr, Goffset *pos) {
   653	  int w[3];
   654	  bool more;
   655	  Object obj;
   656	
   657	  ok = false;
   658	
   659	  Dict *dict = xrefStr->getDict();
   660	  obj = dict->lookupNF("Size");
   661	  if (!obj.isInt()) {
   662	    return false;
   663	  }
   664	  int newSize = obj.getInt();
   665	  if (newSize < 0) {
   666	    return false;
   667	  }
   668	  if (newSize > size) {
   669	    if (resize(newSize) != newSize) {
   670	      error(errSyntaxError, -1, "Invalid 'size' parameter");
   671	      return false;
   672	    }
   673	  }
   674	
   675	  obj = dict->lookupNF("W");
   676	  if (!obj.isArray() || obj.arrayGetLength() < 3) {
   677	    return false;
   678	  }
   679	  for (int i = 0; i < 3; ++i) {
   680	    Object obj2 = obj.arrayGet(i);
   681	    if (!obj2.isInt()) {
   682	      return false;
   683	    }
   684	    w[i] = obj2.getInt();
   685	    if (w[i] < 0) {
