  1075	Object XRef::fetch(int num, int gen, int recursion) {
  1076	  XRefEntry *e;
  1077	  Parser *parser;
  1078	  Object obj1, obj2, obj3;
  1079	
  1080	  xrefLocker();
  1081	  // check for bogus ref - this can happen in corrupted PDF files
  1082	  if (num < 0 || num >= size) {
  1083	    goto err;
  1084	  }
  1085	
  1086	  e = getEntry(num);
  1087	  if(!e->obj.isNull ()) { //check for updated object
  1088	    return e->obj.copy();
  1089	  }
  1090	
  1091	  switch (e->type) {
  1092	
  1093	  case xrefEntryUncompressed:
  1094	  {
  1095	    if (e->gen != gen || e->offset < 0) {
  1096	      goto err;
  1097	    }
  1098	    parser = new Parser(this,
  1099		       new Lexer(this,
  1100			 str->makeSubStream(start + e->offset, false, 0, Object(objNull))),
  1101		       true);
  1102	    obj1 = parser->getObj(recursion);
  1103	    obj2 = parser->getObj(recursion);
  1104	    obj3 = parser->getObj(recursion);
  1105	    if (!obj1.isInt() || obj1.getInt() != num ||
  1106		!obj2.isInt() || obj2.getInt() != gen ||
  1107		!obj3.isCmd("obj")) {
  1108	      // some buggy pdf have obj1234 for ints that represent 1234
  1109	      // try to recover here
  1110	      if (obj1.isInt() && obj1.getInt() == num &&
  1111		  obj2.isInt() && obj2.getInt() == gen &&
  1112		  obj3.isCmd()) {
  1113		const char *cmd = obj3.getCmd();
  1114		if (strlen(cmd) > 3 &&
  1115		    cmd[0] == 'o' &&
  1116		    cmd[1] == 'b' &&
  1117		    cmd[2] == 'j') {
  1118		  char *end_ptr;
  1119		  long longNumber = strtol(cmd + 3, &end_ptr, 0);
  1120		  if (longNumber <= INT_MAX && longNumber >= INT_MIN && *end_ptr == '\0') {
  1121		    int number = longNumber;
  1122		    error(errSyntaxWarning, -1, "Cmd was not obj but {0:s}, assuming the creator meant obj {1:d}", cmd, number);
  1123		    delete parser;
  1124		    return Object(number);
  1125		  }
  1126		}
  1127	      }
  1128	      delete parser;
  1129	      goto err;
  1130	    }
  1131	    Object obj = parser->getObj(false, (encrypted && !e->getFlag(XRefEntry::Unencrypted)) ? fileKey : nullptr,
  1132			   encAlgorithm, keyLength, num, gen, recursion);
  1133	    delete parser;
  1134	    return obj;
  1135	  }
  1136	
  1137	  case xrefEntryCompressed:
  1138	  {
  1139	#if 0 // Adobe apparently ignores the generation number on compressed objects
  1140	    if (gen != 0) {
  1141	      goto err;
  1142	    }
  1143	#endif
  1144	    if (e->offset >= (Guint)size ||
  1145		entries[e->offset].type != xrefEntryUncompressed) {
  1146	      error(errSyntaxError, -1, "Invalid object stream");
  1147	      goto err;
  1148	    }
  1149	
  1150	    ObjectStream *objStr = objStrs.lookup(e->offset);
  1151	    if (!objStr) {
  1152	      objStr = new ObjectStream(this, e->offset, recursion + 1);
  1153	      if (!objStr->isOk()) {
  1154		delete objStr;
  1155		objStr = nullptr;
  1156		goto err;
  1157	      } else {
  1158		// XRef could be reconstructed in constructor of ObjectStream:
  1159		e = getEntry(num);
  1160		objStrs.put(e->offset, objStr);
  1160		objStrs.put(e->offset, objStr);
  1161	      }
  1162	    }
  1163	    return objStr->getObject(e->gen, num);
  1164	  }
  1165	
  1166	  default:
  1167	    goto err;
  1168	  }
  1169	  
  1170	 err:
  1171	  if (!xRefStream && !xrefReconstructed) {
  1172	    error(errInternal, -1, "xref num {0:d} not found but needed, try to reconstruct\n", num);
  1173	    rootNum = -1;
  1174	    constructXRef(&xrefReconstructed);
  1175	    return fetch(num, gen, ++recursion);
  1176	  }
  1177	  return Object(objNull);
  1178	}
