  1269	void XRef::add(int num, int gen, Goffset offs, bool used) {
  1270	  xrefLocker();
  1271	  if (num >= size) {
  1272	    if (num >= capacity) {
  1273	      entries = (XRefEntry *)greallocn(entries, num + 1, sizeof(XRefEntry));
  1274	      capacity = num + 1;
  1275	    }
  1276	    for (int i = size; i < num + 1; ++i) {
  1277	      entries[i].offset = -1;
  1278	      entries[i].type = xrefEntryFree;
  1279	      new (&entries[i].obj) Object(objNull);
  1280	      entries[i].flags = 0;
  1281	      entries[i].gen = 0;
  1282	    }
  1283	    size = num + 1;
  1284	  }
  1285	  XRefEntry *e = getEntry(num);
  1286	  e->gen = gen;
  1287	  e->obj.setToNull();
  1288	  e->flags = 0;
  1289	  if (used) {
  1290	    e->type = xrefEntryUncompressed;
  1291	    e->offset = offs;
  1292	  } else {
  1293	    e->type = xrefEntryFree;
  1294	    e->offset = 0;
  1295	  }
  1296	}
