  1310	Ref XRef::addIndirectObject (const Object *o) {
  1311	  int entryIndexToUse = -1;
  1312	  for (int i = 1; entryIndexToUse == -1 && i < size; ++i) {
  1313	    XRefEntry *e = getEntry(i, false /* complainIfMissing */);
  1314	    if (e->type == xrefEntryFree && e->gen != 65535) {
  1315	      entryIndexToUse = i;
  1316	    }
  1317	  }
  1318	
  1319	  XRefEntry *e;
  1320	  if (entryIndexToUse == -1) {
  1321	    entryIndexToUse = size;
  1322	    add(entryIndexToUse, 0, 0, false);
  1323	    e = getEntry(entryIndexToUse);
  1324	  } else {
  1325	    //reuse a free entry
  1326	    e = getEntry(entryIndexToUse);
  1327	    //we don't touch gen number, because it should have been 
  1328	    //incremented when the object was deleted
  1329	  }
  1330	  e->type = xrefEntryUncompressed;
  1331	  e->obj = o->copy();
  1332	  e->setFlag(XRefEntry::Updated, true);
  1333	  setModified();
  1334	
  1335	  Ref r;
  1336	  r.num = entryIndexToUse;
  1337	  r.gen = e->gen;
  1338	  return r;
  1339	}
