  1341	void XRef::removeIndirectObject(Ref r) {
  1342	  xrefLocker();
  1343	  if (r.num < 0 || r.num >= size) {
  1344	    error(errInternal, -1,"XRef::removeIndirectObject on unknown ref: {0:d}, {1:d}\n", r.num, r.gen);
  1345	    return;
  1346	  }
  1347	  XRefEntry *e = getEntry(r.num);
  1348	  if (e->type == xrefEntryFree) {
  1349	    return;
  1350	  }
  1351	  e->obj.~Object();
  1352	  e->type = xrefEntryFree;
  1353	  e->gen++;
  1354	  e->setFlag(XRefEntry::Updated, true);
  1355	  setModified();
  1356	}
